import random, re
ТЕХ = re.compile(r"(?i)техн\w* директор|главн\w* (инженер|технолог|энергетик|механик)|производств|технолог|энергетик|механик|начальник цеха")
РУК = re.compile(r"(?i)директор|руковод|управляющ")
def ранг(д):
    if ТЕХ.search(д): return 0
    if РУК.search(д) and not re.search(r"(?i)закуп|снабж|продаж|коммерч|маркет|финанс|бухгалт", д): return 1
    if re.search(r"(?i)закуп|снабж", д): return 2
    return 3
ИМЕНА = set("""александр алексей анатолий андрей антон аркадий артём артем борис вадим валентин валерий василий виктор виталий владимир владислав вячеслав геннадий георгий глеб григорий даниил денис дмитрий евгений егор иван игорь илья кирилл константин леонид максим марат михаил никита николай олег павел пётр петр роман руслан рустам сергей станислав степан тимур фёдор федор эдуард юрий ярослав
александра алина алла анастасия анна антонина валентина валерия вера виктория галина дарья евгения екатерина елена жанна зинаида зоя инна ирина карина кристина лариса лидия любовь людмила маргарита марина мария надежда наталья наталия нина оксана ольга полина раиса светлана софья тамара татьяна ульяна юлия яна""".split())
def обращение(fio):
    ч = [x for x in re.split(r"\s+", (fio or "").strip()) if x]
    if any(len(x.strip(".")) <= 2 or "." in x for x in ч): return None
    for i, x in enumerate(ч):
        if re.search(r"(вич|вна|ична|ьич)$", x, re.I) and i > 0 and ч[i - 1].lower() in ИМЕНА: return ч[i - 1] + " " + x
    for x in ч:
        if x.lower() in ИМЕНА: return x
    return None
# ---- кандидаты: на отрасль до 6 по имени (лучшая роль) + до 4 без имени; модель отсеет несоответствие
ПЛОХ_АДР = re.compile(r"(?i)@(site|example|test)\.(ru|com)$|\.(ua|by|kz|uz|am|ge|az|md)$")
def адрес_годен(em):
    em = (em or "").strip().lower()
    return bool(re.match(r"^[\w.+-]+@[\w.-]+\.(ru|рф|su|com|org|net|pro|biz|info)$", em)) and not ПЛОХ_АДР.search(em)
