def отсев_кодом(р, отр, с):
    """Причина отсева компании кодом или "". р — строка файла заливки, с — строка полной базы по ИНН."""
    тут = " ".join([р.get("Продукция") or "", с.get("Продукция") or "", с.get("Оборудование, линии") or "", р.get("Компания") or ""])
    к = КОНК_РЕ.search(" ".join([р.get("Продукция") or "", с.get("Продукция") or "", с.get("Газы (паспорт)") or ""]))
    if к: return "конкурент (код: «%s»)" % к.group(0)
    for о, кл in ОБЯЗ:
        if re.search(о, отр) and not re.search(кл, тут): return "нет признаков отрасли"
    if re.search(r"(?i)золот", отр) and (re.search(r"(?i)россыпн", тут) or not re.search(r"(?i)руд|фабрик|зиф|цианир|обогат|кучн|выщелач|cil|cip", тут)):
        return "золото без ЗИФ/цианирования"
    if re.search(r"(?i)кофе", отр) and re.search(r"(?i)вендинг|автомат\w*\s+(unicum|necta|saeco|jettino)|парк оборудования|кофемашин|кофейн", тут):
        return "вендинг/кофемашины"
    if not (р.get("Продукция") or "").strip(): return "нет продукции"
    return ""
def фраза(f, газ):
    """Нормализация + проверка фразы модели. -> (фраза, беда)."""
    f = re.sub(r"\s*—\s*", " - ", (f or "").strip())
    if f and not re.search(r"[.!?]$", f): f += "."
    беда = годна(f)
    if not беда and газ == "O2" and re.search(r"(?i)резк|режут|резать|заправ", f): беда = "O2: резка/заправка"
    return f, беда
